actions.script:
// the terminal's agenda: the next four weeks
agendaRows = []
const projectId = ec.context.get('projectTabId') || null
if (!projectId) return
const today = ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
const first = /^\d{4}-\d{2}-\d{2}$/.test(String(date || '')) ? String(date) : today
const d = new Date(first + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + 27)
const out = ec.service.sync().name('ironstone.projects.PlanningServices.get#ProjectCalendarEvents').parameters({rootWorkEffortId: projectId, start: first,
end: d.toISOString().substring(0, 10)}).call() || {}
ec.message.clearErrors()
const kinds = {event: 'Meeting', task: 'Work item due', milestone: 'Milestone', release: 'Release', sprint: 'Sprint'}
agendaRows = Array.from(out.eventList || []).map((event) => ({when: String(event.start).substring(0, 16),
kind: ec.l10n.localize(kinds[event.kind] || 'Event'), title: event.title, url: event.url || ''})).sort((a, b) => a.when.localeCompare(b.when))
